<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { fetchAssetDetail, fetchAssetTree, sortAssetTreeForDisplay, type AssetTreeNode } from '../../api/asset'
import { fetchPointPage, type PointDefinition } from '../../api/point'
import { createRule, deleteRule, editRule, fetchRuleDetail, fetchRuleEvents, fetchRuleOptions, fetchRulePage, fetchRuleTasks, toggleRule, type RuleAction, type RuleConfig, type RuleEvent, type RuleListItem, type RuleOptions, type RuleTask } from '../../api/rule'
import { fetchControlPage, type ControlListItem } from '../../api/control'
import ConfirmModal from '../modals/ConfirmModal.vue'
import RdfGraphModal from '../modals/rule/RdfGraphModal.vue'

type Tab = 'rules' | 'events' | 'tasks'
type EditorSection = 'info' | 'target' | 'condition' | 'policy' | 'actions'
type ComparisonForm = { operator: string; leftType: string; constant: number; samples: number; duration: number; tolerance: number; window: number; timeUnit: number; rateReference: 'samples' | 'duration' }
const tab = ref<Tab>('rules'); const loading = ref(false); const error = ref(''); const page = ref(1); const pageSize = 10; const total = ref(0)
const rules = ref<RuleListItem[]>([]); const events = ref<RuleEvent[]>([]); const tasks = ref<RuleTask[]>([])
const totalPages = computed(() => Math.max(1, Math.ceil(total.value / pageSize)))
const filters = reactive({ rule_name: '', status: '', create_at: '', rule_id: '', event_type: '', event_time: '', action_type: '', task_status: '', create_time: '' })
const statusMap: Record<string,string> = { paused:'已暂停',running:'运行中',validating:'校验中',compile_failed:'编译失败',pending:'待执行',succeeded:'成功',failed:'失败' }

async function load(targetPage = 1) { loading.value = true; error.value = ''; page.value = targetPage; try { if (tab.value === 'rules') { const r = await fetchRulePage(targetPage,pageSize,Object.fromEntries(Object.entries({rule_name:filters.rule_name,status:filters.status,create_at:filters.create_at}).filter(([,v])=>v))); rules.value=r.data;total.value=r.total } else if(tab.value==='events'){const r=await fetchRuleEvents(targetPage,pageSize,Object.fromEntries(Object.entries({rule_id:filters.rule_id,event_type:filters.event_type,event_time:filters.event_time}).filter(([,v])=>v)));events.value=r.data;total.value=r.total}else{const r=await fetchRuleTasks(targetPage,pageSize,Object.fromEntries(Object.entries({rule_id:filters.rule_id,action_type:filters.action_type,status:filters.task_status,create_time:filters.create_time}).filter(([,v])=>v)));tasks.value=r.data;total.value=r.total} } catch(e:any){error.value=e?.message||'加载失败'}finally{loading.value=false} }
function changeTab(value:Tab){tab.value=value;page.value=1;load(1)}
function clearFilters(){Object.keys(filters).forEach(key=>(filters as any)[key]='');load(1)}
function fmt(value:string|null){if(!value)return'—';const d=new Date(value);return Number.isNaN(d.getTime())?value:d.toLocaleString('zh-CN',{hour12:false})}

const options=ref<RuleOptions|null>(null);const assets=ref<AssetTreeNode[]>([]);const globalPoints=ref<PointDefinition[]>([]);const controls=ref<ControlListItem[]>([]);const controlsLoading=ref(false);const editor=ref(false);const editorMode=ref<'create'|'edit'>('create');const editorLoading=ref(false);const editId=ref('');const sensorId=ref('');const sensorPoints=ref<any[]>([]);const sensorLoading=ref(false)
const editorSection=ref<EditorSection>('info')
const form=reactive({rule_name:'',description:'',selector_id:'monitor',selector_type:'PointIdSelector' as 'PointIdSelector'|'SemanticPointSelector',point_id:'',point_definition_id:'',location_id:'',location_type:'' as ''|'building'|'floor'|'room',logic:'single' as 'single'|'AND'|'OR'|'NOT',trigger_count:1,trigger_duration:0,recovery_count:1,recovery_duration:0,repeat_policy:'OncePerIncident',repeat_interval:60,cooldown:0,merge_window:0})
const comparisons=ref<ComparisonForm[]>([]);const actions=ref<RuleAction[]>([])
const activeActionIndex=ref(0)
const newActionType=ref<'LogAction'|'EmailAction'|'SensorControlAction'>('LogAction')
const placeholderSelections=ref<string[]>([])
const placeholderOptions=[{value:'{{$.point_name}}',label:'测点名称'},{value:'{{$.time}}',label:'测量时间'},{value:'{{$.value}}',label:'测量数值'}]
const sensors=computed(()=>{const result:{id:string;name:string;path:string}[]=[];for(const b of assets.value)for(const f of b.sub_assets||[])for(const r of f.sub_assets||[])for(const t of r.sub_assets||[])for(const s of t.sub_assets||[])result.push({id:s.asset_id,name:s.name,path:`${b.name} / ${f.name} / ${r.name} / ${t.name}`});return result})
const selectedSensor=computed(()=>sensors.value.find(item=>item.id===sensorId.value))
const selectedPoint=computed(()=>sensorPoints.value.find(item=>item.point_id===form.point_id))
const selectedDefinition=computed(()=>globalPoints.value.find(item=>item.point_id===form.point_definition_id))
const semanticLocations=computed(()=>{const result:{id:string;name:string;path:string;type:'building'|'floor'|'room'}[]=[];for(const b of assets.value){result.push({id:b.asset_id,name:b.name,path:b.name,type:'building'});for(const f of b.sub_assets||[]){result.push({id:f.asset_id,name:f.name,path:`${b.name} / ${f.name}`,type:'floor'});for(const r of f.sub_assets||[])result.push({id:r.asset_id,name:r.name,path:`${b.name} / ${f.name} / ${r.name}`,type:'room'})}}return result})
const selectedLocation=computed(()=>semanticLocations.value.find(item=>item.id===form.location_id))
const editorSteps=computed(()=>[
  {key:'info' as EditorSection,title:'规则信息',summary:form.rule_name||'设置名称与描述',done:!!form.rule_name.trim()},
  {key:'target' as EditorSection,title:'规则监控对象',summary:form.selector_type==='PointIdSelector'?(selectedPoint.value?.point_name||selectedPoint.value?.name||selectedSensor.value?.name||'选择传感器与测点'):(selectedDefinition.value?.point_name&&selectedLocation.value?`${selectedLocation.value.name} / ${selectedDefinition.value.point_name}`:'选择位置与全局测点'),done:form.selector_type==='PointIdSelector'?(!!sensorId.value&&!!form.point_id):(!!form.point_definition_id&&!!form.location_id)},
  {key:'condition' as EditorSection,title:'规则触发条件',summary:`${form.logic==='single'?'单一条件':form.logic} · ${comparisons.value.length} 项`,done:comparisons.value.length>0},
  {key:'policy' as EditorSection,title:'规则触发策略',summary:`触发 ${form.trigger_count} 次 · ${form.repeat_policy}`,done:Number(form.trigger_count)>0},
  {key:'actions' as EditorSection,title:'规则触发任务',summary:`${actions.value.length} 个执行任务`,done:actions.value.length>0},
])
function newComparison():ComparisonForm{return{operator:'GreaterThan',leftType:'PointValue',constant:40,samples:1,duration:60,tolerance:5,window:300,timeUnit:60,rateReference:'samples'}}
function resetEditor(){Object.assign(form,{rule_name:'',description:'',selector_id:'monitor',selector_type:'PointIdSelector',point_id:'',point_definition_id:'',location_id:'',location_type:'',logic:'single',trigger_count:1,trigger_duration:0,recovery_count:1,recovery_duration:0,repeat_policy:'OncePerIncident',repeat_interval:60,cooldown:0,merge_window:0});comparisons.value=[newComparison()];actions.value=[{type:'LogAction',params:{level:'WARNING',content:'{{$.point_name}} 在 {{$.time}} 的值为 {{$.value}}'}}];placeholderSelections.value=[''];newActionType.value='LogAction';activeActionIndex.value=0;sensorId.value='';sensorPoints.value=[];editorSection.value='info'}
async function loadGlobalPoints(){if(globalPoints.value.length)return;const first=await fetchPointPage(1,100);globalPoints.value=first.data;const pages=Math.ceil(first.total/100);if(pages>1){const rest=await Promise.all(Array.from({length:pages-1},(_,i)=>fetchPointPage(i+2,100)));globalPoints.value.push(...rest.flatMap(item=>item.data))}}
async function loadControls(){if(controls.value.length||controlsLoading.value)return;controlsLoading.value=true;try{const first=await fetchControlPage(1,100,{});const normalize=(item:ControlListItem)=>({...item,sensor_name:controlAssetLabel(item)});controls.value=first.data.map(normalize);const pages=Math.ceil(first.total/100);if(pages>1){const rest=await Promise.all(Array.from({length:pages-1},(_,i)=>fetchControlPage(i+2,100,{})));controls.value.push(...rest.flatMap(item=>item.data).map(normalize))}}finally{controlsLoading.value=false}}
async function ensureEditorData(){if(!options.value)options.value=await fetchRuleOptions();if(!assets.value.length)assets.value=sortAssetTreeForDisplay(await fetchAssetTree());await loadControls()}
async function chooseSelectorType(type:'PointIdSelector'|'SemanticPointSelector'){form.selector_type=type;error.value='';if(type==='SemanticPointSelector'){try{await loadGlobalPoints()}catch(e:any){error.value=e?.message||'加载全局测点失败'}}}
watch(()=>form.selector_type,type=>{if(type==='SemanticPointSelector'&&!globalPoints.value.length)loadGlobalPoints().catch((e:any)=>{error.value=e?.message||'加载全局测点失败'})})
async function openCreate(){editorMode.value='create';editId.value='';resetEditor();error.value='';editor.value=true;try{await ensureEditorData()}catch(e:any){error.value=e?.message||'加载规则配置失败'}}
function parseOperand(node:any,c:ComparisonForm){c.leftType=node?.type||'PointValue';c.samples=node?.samples??1;c.duration=node?.duration_seconds??60;c.tolerance=node?.tolerance_seconds??5;c.window=node?.window_seconds??300;c.timeUnit=node?.time_unit_seconds??60;c.rateReference=node?.samples?'samples':'duration'}
async function openEdit(item:RuleListItem){editorMode.value='edit';editId.value=item.rule_id;resetEditor();editor.value=true;editorLoading.value=true;try{await ensureEditorData();const detail=await fetchRuleDetail(item.rule_id);if(!detail.config)throw new Error('当前规则配置无法解析，只能查看图谱或删除');const c:any=detail.config;const selector=c.selector||{};form.rule_name=c.rule_name;form.description=c.description||'';form.selector_id=selector.selector_id||'monitor';form.selector_type=selector.type||'PointIdSelector';form.point_id=selector.point_id||'';form.point_definition_id=selector.point_definition_id||'';form.location_id=selector.location_id||'';form.location_type=selector.location_type||'';sensorId.value=detail.sensor_id||'';if(sensorId.value)await loadSensorPoints(true);const cond:any=c.condition;if(cond.type==='Logical'){form.logic=cond.operator;comparisons.value=(cond.children||[]).map((child:any)=>{const row=newComparison();row.operator=child.operator;parseOperand(child.left,row);row.constant=Number(child.right?.value??0);return row})}else{form.logic='single';const row=newComparison();row.operator=cond.operator;parseOperand(cond.left,row);row.constant=Number(cond.right?.value??0);comparisons.value=[row]}const p:any=c.trigger_policy||{};Object.assign(form,{trigger_count:p.trigger_count??1,trigger_duration:p.trigger_duration_seconds??0,recovery_count:p.recovery_count??1,recovery_duration:p.recovery_duration_seconds??0,repeat_policy:p.repeat_policy||'OncePerIncident',repeat_interval:p.repeat_interval_seconds??60,cooldown:p.cooldown_seconds??0,merge_window:p.merge_window_seconds??0});actions.value=(c.actions||[]).map((a:RuleAction)=>({...a,params:{...a.params}}));placeholderSelections.value=actions.value.map(()=>'')}catch(e:any){error.value=e?.message||'加载详情失败'}finally{editorLoading.value=false}}
async function loadSensorPoints(preservePoint=false){const oldPoint=form.point_id;if(!preservePoint)form.point_id='';sensorPoints.value=[];if(!sensorId.value)return;sensorLoading.value=true;try{const d:any=await fetchAssetDetail(sensorId.value);sensorPoints.value=d.sensor_points||d.points||[];if(preservePoint)form.point_id=oldPoint}catch(e:any){error.value=e?.message||'加载实例测点失败'}finally{sensorLoading.value=false}}
async function selectSensor(){await loadSensorPoints(false)}
function operand(row:ComparisonForm){const base:any={type:row.leftType,selector_id:form.selector_id};if(row.leftType==='SampleLagDifference')base.samples=row.samples;if(row.leftType==='TimeLagDifference'){base.duration_seconds=row.duration;base.tolerance_seconds=row.tolerance}if(['WindowAverageDifference','WindowRange'].includes(row.leftType))base.window_seconds=row.window;if(row.leftType==='RateOfChange'){base.time_unit_seconds=row.timeUnit;if(row.rateReference==='samples')base.samples=row.samples;else{base.duration_seconds=row.duration;base.tolerance_seconds=row.tolerance}}return base}
function buildConfig():RuleConfig{const nodes=comparisons.value.map(c=>({type:'Comparison',operator:c.operator,left:operand(c),right:{type:'ConstantValue',value:Number(c.constant)}}));const condition:any=form.logic==='single'?nodes[0]:{type:'Logical',operator:form.logic,children:form.logic==='NOT'?[nodes[0]]:nodes};const selector=form.selector_type==='PointIdSelector'?{selector_id:form.selector_id.trim(),type:'PointIdSelector',point_id:form.point_id}:{selector_id:form.selector_id.trim(),type:'SemanticPointSelector',point_definition_id:form.point_definition_id,location_id:form.location_id,location_type:form.location_type};return{rule_name:form.rule_name.trim(),description:form.description.trim(),selector,condition,trigger_policy:{trigger_count:Number(form.trigger_count),trigger_duration_seconds:Number(form.trigger_duration),recovery_count:Number(form.recovery_count),recovery_duration_seconds:Number(form.recovery_duration),repeat_policy:form.repeat_policy,repeat_interval_seconds:form.repeat_policy==='Periodic'?Number(form.repeat_interval):null,cooldown_seconds:Number(form.cooldown),merge_window_seconds:Number(form.merge_window)},actions:actions.value.map(a=>({...a,params:{...a.params}}))}}
function actionError(a:RuleAction){if(a.type==='LogAction')return !a.params.level||!a.params.content?.trim()?'请完整填写日志等级和日志内容':'';if(a.type==='EmailAction'){const recipients=a.params.recipients||[];if(!recipients.length)return'请至少填写一个邮件收件人';if(recipients.length>50)return'邮件收件人不能超过 50 个';if(recipients.some(v=>!/^\S+@\S+\.\S+$/.test(v)))return'邮件收件人格式不正确';if(!a.params.subject?.trim())return'请填写邮件主题';if(a.params.subject.length>200)return'邮件主题不能超过 200 个字符';if(!a.params.content?.trim())return'请填写邮件内容';return''}return !a.params.control_id?'请选择需要执行的 Control':''}
async function saveRule(){error.value='';const targetValid=form.selector_type==='PointIdSelector'?!!form.point_id:(!!form.point_definition_id&&!!form.location_id&&!!form.location_type);if(!form.rule_name.trim()||!form.selector_id.trim()||!targetValid){error.value='请填写规则名称、选择器标识并完整配置监控对象';editorSection.value=!form.rule_name.trim()?'info':'target';return}if((form.logic==='AND'||form.logic==='OR')&&comparisons.value.length<2){error.value='并且/或者条件至少需要两个比较项';editorSection.value='condition';return}const invalidAction=actions.value.map(actionError).find(Boolean);if(!actions.value.length||invalidAction){error.value=invalidAction||'请至少配置一个执行任务';editorSection.value='actions';return}if(form.repeat_policy==='Periodic'&&Number(form.repeat_interval)<=0){error.value='周期触发的重复间隔必须大于 0';editorSection.value='policy';return}editorLoading.value=true;try{const config=buildConfig();if(editorMode.value==='create')await createRule(config);else await editRule(editId.value,config);editor.value=false;await load(1)}catch(e:any){error.value=e?.message||'保存规则失败'}finally{editorLoading.value=false}}
function selectLocation(){const location=semanticLocations.value.find(item=>item.id===form.location_id);form.location_type=location?.type||''}
function addAction(){const type=newActionType.value;const params=type==='LogAction'?{level:'WARNING',content:'{{$.point_name}}={{$.value}}'}:type==='EmailAction'?{recipients:[] as string[],subject:'',content:'{{$.point_name}} 在 {{$.time}} 的值为 {{$.value}}'}:{control_id:''};actions.value.push({type,params});placeholderSelections.value.push('');activeActionIndex.value=actions.value.length-1}
function addPlaceholder(index:number,value:string){const action=actions.value[index];if(action&&action.type!=='SensorControlAction')action.params.content=(action.params.content||'')+value}
function addSelectedPlaceholder(index:number){const value=placeholderSelections.value[index];if(!value)return;addPlaceholder(index,value);placeholderSelections.value[index]=''}
function removeAction(index:number){actions.value.splice(index,1);placeholderSelections.value.splice(index,1);activeActionIndex.value=Math.max(0,Math.min(activeActionIndex.value,actions.value.length-1))}
function recipientsText(action:RuleAction){return(action.params.recipients||[]).join(', ')}
function setRecipients(action:RuleAction,value:string){action.params.recipients=value.split(/[,，;；\n]/).map(item=>item.trim()).filter(Boolean)}
function actionTitle(type:string){return type==='EmailAction'?'邮件任务':type==='SensorControlAction'?'传感器控制任务':'日志任务'}
function controlAssetLabel(control:ControlListItem){return control.asset?.name||control.asset_name||control.sensor_name||control.asset_id||'未知资产'}
async function handleToggle(item:RuleListItem){error.value='';try{await toggleRule(item.rule_id);await load(page.value)}catch(e:any){error.value=e?.message||'切换状态失败'}}
const deleteTarget=ref<RuleListItem|null>(null);const deleting=ref(false);const deleteError=ref('')
const graphTarget=ref<RuleListItem|null>(null)
async function confirmDelete(){if(!deleteTarget.value)return;deleting.value=true;deleteError.value='';try{await deleteRule(deleteTarget.value.rule_id);deleteTarget.value=null;await load(page.value)}catch(e:any){deleteError.value=e?.message||'删除失败'}finally{deleting.value=false}}
onMounted(()=>load())
</script>

<template><main class="page-content"><section class="workspace"><div class="top-tabs"><button :class="{active:tab==='rules'}" @click="changeTab('rules')">规则列表</button><button :class="{active:tab==='events'}" @click="changeTab('events')">规则事件</button><button :class="{active:tab==='tasks'}" @click="changeTab('tasks')">行动任务</button><button v-if="tab==='rules'" class="create" @click="openCreate">＋ 新增规则</button></div><section class="card"><div class="toolbar"><template v-if="tab==='rules'"><input v-model="filters.rule_name" placeholder="规则名称"><select v-model="filters.status"><option value="">全部状态</option><option value="paused">已暂停</option><option value="running">运行中</option><option value="validating">校验中</option><option value="compile_failed">编译失败</option></select><input v-model="filters.create_at" type="date"></template><template v-else-if="tab==='events'"><input v-model="filters.rule_id" placeholder="来源规则 ID"><select v-model="filters.event_type"><option value="">全部事件</option><option value="triggered">触发</option><option value="recovered">恢复</option></select><input v-model="filters.event_time" type="date"></template><template v-else><input v-model="filters.rule_id" placeholder="来源规则 ID"><select v-model="filters.task_status"><option value="">全部状态</option><option value="pending">待执行</option><option value="succeeded">成功</option><option value="failed">失败</option></select><input v-model="filters.create_time" type="date"></template><div class="toolbar-actions"><button @click="clearFilters">清空</button><button class="primary" @click="load(1)">查询</button></div></div><div v-if="error&&!editor" class="alert">{{error}}<button @click="error=''">×</button></div>
<div class="table-area"><table v-if="tab==='rules'"><thead><tr><th>规则名称</th><th>状态</th><th>错误信息</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in rules" :key="r.rule_id"><td><strong>{{r.rule_name}}</strong></td><td><span class="status" :class="r.status">{{statusMap[r.status]}}</span></td><td class="error-cell">{{r.error||'—'}}</td><td>{{fmt(r.created_at)}}</td><td class="actions"><button :disabled="r.status==='running'" @click="openEdit(r)">编辑</button><button :class="r.status==='running'?'warn':'success'" @click="handleToggle(r)">{{r.status==='running'?'暂停':'启动'}}</button><button class="graph-btn" @click="graphTarget=r">图谱</button><button class="danger" :disabled="r.status==='running'" @click="deleteTarget=r">删除</button></td></tr></tbody></table>
<table v-else-if="tab==='events'"><thead><tr><th>事件类型</th><th>测点</th><th>测量值</th><th>原因</th><th>事件时间</th></tr></thead><tbody><tr v-for="e in events" :key="e.event_id"><td><span class="status" :class="e.event_type">{{e.event_type==='triggered'?'触发':'恢复'}}</span></td><td>{{e.evidence?.point_name||'—'}} <small>{{e.evidence?.unit}}</small></td><td><strong>{{e.evidence?.value??'—'}}</strong></td><td>{{e.evidence?.reason||'—'}}</td><td>{{fmt(e.event_time)}}</td></tr></tbody></table>
<table v-else><thead><tr><th>行动类型</th><th>状态</th><th>是否执行</th><th>错误信息</th><th>创建时间</th><th>完成时间</th></tr></thead><tbody><tr v-for="t in tasks" :key="t.task_id"><td>{{t.action_type}}</td><td><span class="status" :class="t.status">{{statusMap[t.status]}}</span></td><td>{{t.is_executed?'是':'否'}}</td><td class="error-cell">{{t.error||'—'}}</td><td>{{fmt(t.created_at)}}</td><td>{{fmt(t.completed_at)}}</td></tr></tbody></table><div v-if="loading" class="empty">加载中...</div><div v-else-if="(tab==='rules'&&!rules.length)||(tab==='events'&&!events.length)||(tab==='tasks'&&!tasks.length)" class="empty">暂无数据</div></div><div class="pagination" v-if="total"><span>共 {{total}} 条</span><button :disabled="page<=1" @click="load(page-1)">上一页</button><b>{{page}} / {{totalPages}}</b><button :disabled="page>=totalPages" @click="load(page+1)">下一页</button></div></section></section>

<div v-if="editor" class="overlay" @click.self="editor=false"><form class="editor editor-wide" @submit.prevent="saveRule"><header><div><h2>{{editorMode==='create'?'新增规则':'编辑规则'}}</h2><p>按模块完成规则配置，左侧可随时切换</p></div><button type="button" @click="editor=false">×</button></header><div class="editor-layout"><aside class="editor-overview"><div class="overview-title">配置概览 <small>{{editorSteps.filter(s=>s.done).length}} / 5</small></div><button v-for="(step,index) in editorSteps" :key="step.key" type="button" :class="{active:editorSection===step.key,done:step.done}" @click="editorSection=step.key"><i>{{step.done?'✓':index+1}}</i><span><strong>{{step.title}}</strong><small>{{step.summary}}</small></span><b>›</b></button></aside><div class="editor-body module-body"><div v-if="editorLoading" class="loading-mask">处理中...</div>
<section v-if="editorSection==='info'"><div class="module-heading"><span>01</span><div><h3>规则信息</h3><p>设置用于识别这条规则的名称和说明</p></div></div><div class="form-grid"><label>规则名称<input v-model="form.rule_name" maxlength="100" placeholder="请输入规则名称"></label><label>选择器标识<input v-model="form.selector_id" maxlength="100" placeholder="例如 monitor"></label><label class="wide">规则描述<textarea v-model="form.description" maxlength="1000" rows="5" placeholder="说明规则用途和适用场景"></textarea></label></div></section>
<section v-else-if="editorSection==='target'"><div class="module-heading"><span>02</span><div><h3>规则监控对象</h3><p>监控一个实例测点，或匹配指定位置下同定义的全部测点</p></div></div><div class="selector-switch"><button type="button" :class="{active:form.selector_type==='PointIdSelector'}" @click="form.selector_type='PointIdSelector'"><b>实例测点</b><small>精确监控一个传感器实例测点</small></button><button type="button" :class="{active:form.selector_type==='SemanticPointSelector'}" @click="form.selector_type='SemanticPointSelector'"><b>语义测点</b><small>监控位置下同一类型的全部测点</small></button></div><div v-if="form.selector_type==='PointIdSelector'" class="form-grid"><label class="wide">选择传感器<select v-model="sensorId" @change="selectSensor"><option value="">请选择传感器</option><option v-for="s in sensors" :key="s.id" :value="s.id">{{s.path}} / {{s.name}}</option></select></label><label class="wide">监控测点<select v-model="form.point_id" :disabled="!sensorId||sensorLoading"><option value="">{{sensorLoading?'正在加载测点...':'请选择实例测点'}}</option><option v-if="form.point_id&&!sensorPoints.some(p=>p.point_id===form.point_id)" :value="form.point_id">当前测点（{{form.point_id}}）</option><option v-for="p in sensorPoints" :key="p.point_id" :value="p.point_id">{{p.point_name||p.name||p.point_id}} {{p.point_unit||p.unit||''}}</option></select></label><div v-if="selectedPoint" class="selection-card wide"><b>{{selectedPoint.point_name||selectedPoint.name}}</b><span>{{selectedSensor?.path}} / {{selectedSensor?.name}}</span><small>{{selectedPoint.point_unit||selectedPoint.unit||'无单位'}}</small></div></div><div v-else class="form-grid"><label class="wide">匹配位置<select v-model="form.location_id" @change="selectLocation"><option value="">请选择楼宇、楼层或房间</option><optgroup label="楼宇"><option v-for="item in semanticLocations.filter(i=>i.type==='building')" :key="item.id" :value="item.id">{{item.path}}</option></optgroup><optgroup label="楼层"><option v-for="item in semanticLocations.filter(i=>i.type==='floor')" :key="item.id" :value="item.id">{{item.path}}</option></optgroup><optgroup label="房间"><option v-for="item in semanticLocations.filter(i=>i.type==='room')" :key="item.id" :value="item.id">{{item.path}}</option></optgroup></select></label><label class="wide">全局测点定义<select v-model="form.point_definition_id"><option value="">请选择全局测点</option><option v-for="point in globalPoints" :key="point.point_id" :value="point.point_id">{{point.point_name}}（{{point.point_unit||'无单位'}}）{{point.point_description?' · '+point.point_description:''}}</option></select></label><div v-if="selectedDefinition&&selectedLocation" class="selection-card semantic-card wide"><b>{{selectedDefinition.point_name}}</b><span>{{selectedLocation.path}} 下的全部后代 · {{selectedLocation.type==='building'?'楼宇':selectedLocation.type==='floor'?'楼层':'房间'}}范围</span><small>{{selectedDefinition.point_unit||'无单位'}}</small></div><p class="semantic-tip wide">启用规则时会自动匹配该位置下使用此全局测点定义的实例测点，每个匹配测点独立运行。</p></div></section>
<section v-else-if="editorSection==='condition'"><div class="module-heading"><span>03</span><div><h3>规则触发条件</h3><p>配置测点值满足何种条件时进入触发判定</p></div></div><div class="condition-toolbar"><label>条件组合<select v-model="form.logic"><option value="single">单一条件</option><option value="AND">全部满足（AND）</option><option value="OR">任一满足（OR）</option><option value="NOT">条件取反（NOT）</option></select></label><button v-if="form.logic==='AND'||form.logic==='OR'" type="button" class="add-node" @click="comparisons.push(newComparison())"><b>＋</b> 添加比较节点</button></div><div class="condition-list"><div v-for="(c,i) in comparisons" :key="i" class="condition-row"><span class="number">{{i+1}}</span><select v-model="c.leftType"><option v-for="o in options?.operand_types||[]" :key="o.value" :value="o.value">{{o.label}}</option></select><div class="params"><input v-if="c.leftType==='SampleLagDifference'||(c.leftType==='RateOfChange'&&c.rateReference==='samples')" v-model.number="c.samples" min="1" type="number" placeholder="样本数"><input v-if="c.leftType==='TimeLagDifference'||(c.leftType==='RateOfChange'&&c.rateReference==='duration')" v-model.number="c.duration" min="1" type="number" placeholder="间隔秒"><input v-if="c.leftType==='TimeLagDifference'||(c.leftType==='RateOfChange'&&c.rateReference==='duration')" v-model.number="c.tolerance" min="0" type="number" placeholder="容差秒"><input v-if="['WindowAverageDifference','WindowRange'].includes(c.leftType)" v-model.number="c.window" min="1" type="number" placeholder="窗口秒"><template v-if="c.leftType==='RateOfChange'"><select v-model="c.rateReference"><option value="samples">按样本</option><option value="duration">按时间</option></select><input v-model.number="c.timeUnit" min="1" type="number" placeholder="单位秒"></template></div><select v-model="c.operator"><option v-for="o in options?.comparison_operators||[]" :key="o.value" :value="o.value">{{o.label}} {{o.symbol}}</option></select><input v-model.number="c.constant" type="number" step="any" placeholder="比较常量"><button v-if="comparisons.length>1" type="button" class="remove" title="删除比较节点" @click="comparisons.splice(i,1)">×</button></div></div></section>
<section v-else-if="editorSection==='policy'"><div class="module-heading"><span>04</span><div><h3>规则触发策略</h3><p>控制条件持续多久才触发，以及恢复和重复执行方式</p></div></div><div class="policy-list"><label><span><b>连续触发次数</b><small>条件连续成立多少次后确认触发，避免单次异常造成误报。</small></span><input v-model.number="form.trigger_count" min="1" type="number"></label><label><span><b>触发持续时间</b><small>条件至少持续多少秒才触发；设为 0 表示不要求持续时间。</small></span><div class="unit-input"><input v-model.number="form.trigger_duration" min="0" type="number"><i>秒</i></div></label><label><span><b>连续恢复次数</b><small>条件连续不成立多少次后确认恢复。</small></span><input v-model.number="form.recovery_count" min="1" type="number"></label><label><span><b>恢复持续时间</b><small>恢复状态至少持续多少秒才结束本次事件。</small></span><div class="unit-input"><input v-model.number="form.recovery_duration" min="0" type="number"><i>秒</i></div></label><label><span><b>重复执行策略</b><small>控制同一次未恢复事件中的任务是否重复执行。</small></span><select v-model="form.repeat_policy"><option v-for="p in options?.repeat_policies||[]" :key="p.value" :value="p.value">{{p.label}}</option></select></label><label v-if="form.repeat_policy==='Periodic'"><span><b>重复执行间隔</b><small>事件持续期间，每隔多少秒再次创建触发任务。</small></span><div class="unit-input"><input v-model.number="form.repeat_interval" min="1" type="number"><i>秒</i></div></label><label><span><b>冷却时间</b><small>一次触发后暂停再次触发的时长，用于抑制频繁告警。</small></span><div class="unit-input"><input v-model.number="form.cooldown" min="0" type="number"><i>秒</i></div></label><label><span><b>任务合并窗口</b><small>仅对邮件任务生效；日志和传感器控制任务始终按事件逐次执行。</small></span><div class="unit-input"><input v-model.number="form.merge_window" min="0" type="number"><i>秒</i></div></label></div></section>
<section v-else><div class="module-heading"><span>05</span><div><h3>规则触发任务</h3><p>配置触发后记录日志、发送邮件或执行已保存的传感器控制</p></div><div class="add-task-group"><select v-model="newActionType"><option value="LogAction">日志任务</option><option value="EmailAction">邮件任务</option><option value="SensorControlAction">传感器控制</option></select><button type="button" class="add-task" @click="addAction">＋ 添加任务</button></div></div><div class="task-list"><article v-for="(a,i) in actions" :key="a.action_id||i" class="task-card" :class="['task-'+a.type,{active:activeActionIndex===i}]" @click="activeActionIndex=i"><header><div><span>{{actionTitle(a.type)}}</span><small>{{a.type}}</small></div><button type="button" class="task-delete" @click.stop="removeAction(i)" title="删除任务"><i>×</i><span>删除</span></button></header><div v-if="a.type==='LogAction'" class="task-fields"><label>日志等级<select v-model="a.params.level"><option v-for="l in ['DEBUG','INFO','WARNING','ERROR','CRITICAL']" :key="l">{{l}}</option></select></label><label class="content-editor"><span class="content-title"><b>日志内容</b><span class="field-variable-actions"><select v-model="placeholderSelections[i]"><option value="">选择内容变量</option><option v-for="p in placeholderOptions" :key="p.value" :value="p.value">{{p.label}}</option></select><button type="button" :disabled="!placeholderSelections[i]" @click.prevent="addSelectedPlaceholder(i)">添加</button></span></span><textarea v-model="a.params.content" maxlength="10000" rows="3" placeholder="输入日志内容"></textarea></label></div><div v-else-if="a.type==='EmailAction'" class="task-fields email-fields"><label class="wide-task">收件人 <small>多个邮箱使用逗号、分号或换行分隔，最多 50 个</small><textarea :value="recipientsText(a)" rows="2" placeholder="ops@example.com, admin@example.com" @change="setRecipients(a,($event.target as HTMLTextAreaElement).value)"></textarea></label><label>邮件主题 <small>固定文本，不支持变量</small><input v-model="a.params.subject" maxlength="200" placeholder="例如：高温告警"></label><label class="content-editor"><span class="content-title"><b>邮件内容</b><span class="field-variable-actions"><select v-model="placeholderSelections[i]"><option value="">选择内容变量</option><option v-for="p in placeholderOptions" :key="p.value" :value="p.value">{{p.label}}</option></select><button type="button" :disabled="!placeholderSelections[i]" @click.prevent="addSelectedPlaceholder(i)">添加</button></span></span><textarea v-model="a.params.content" maxlength="10000" rows="4" placeholder="输入纯文本邮件内容"></textarea></label></div><div v-else class="task-fields control-fields"><label class="wide-task">选择 Control <small>执行时使用 Control 已保存的 Topic、Payload、Header、Params 或 Body</small><select v-model="a.params.control_id" :disabled="controlsLoading"><option value="">{{controlsLoading?'正在加载 Control...':'请选择 Control'}}</option><option v-if="a.params.control_id&&!controls.some(c=>c.control_id===a.params.control_id)" :value="a.params.control_id">当前 Control（{{a.params.control_id}}）</option><option v-for="control in controls" :key="control.control_id" :value="control.control_id">{{control.name}} · {{control.type.toUpperCase()}} · {{control.sensor_name}} · {{control.status?'已启用':'已停用'}}</option></select></label></div></article><div v-if="!actions.length" class="task-empty">尚未添加执行任务，请从右上角选择任务类型后添加。</div></div></section><div v-if="error" class="alert">{{error}}</div></div></div><footer><button type="button" @click="editor=false">取消</button><button class="primary" :disabled="editorLoading">{{editorLoading?'保存中...':'保存规则'}}</button></footer></form></div>
<ConfirmModal :visible="!!deleteTarget" title="删除规则" :message="`确定删除规则「${deleteTarget?.rule_name||''}」吗？相关事件和任务将一并删除。`" confirm-text="删除" :danger="true" :loading="deleting" :error="deleteError" @confirm="confirmDelete" @cancel="deleteTarget=null" />
<RdfGraphModal :visible="!!graphTarget" :rule-id="graphTarget?.rule_id||''" :rule-name="graphTarget?.rule_name||''" @close="graphTarget=null" />
</main></template>

